#include <iostream>

int min2(int a, int b)
{
    return a < b ? a : b;
}

int min3(int a, int b, int c)
{
    return min2(a, min2(b, c));
}

int main()
{
    int a{}, b{}, c{}, d{}, e{}, f{};
    if (!(std::cin >> a >> b >> c >> d >> e >> f)) return 0;

    int first{ min3(a, b, c) };
    int second{ min3(d, e, f) };

    std::cout << first << "\n";
    std::cout << second << "\n";
    std::cout << min2(first, second) << "\n";

    return 0;
}
